mapper.select:
SELECT CM.CUSTOMER_HS_CODE  AS customerHsCode
      ,FAHC.FTA_AGM_HS_CODE AS ftaAgmHsCode
      ,FHC.FTA_HS_CODE      AS ftaHsCode
      ,HIS.HS_CODE          AS historyHsCode
      ,IM.HS_CODE           AS itemHsCode
FROM   ITEM_MST IM
LEFT   OUTER JOIN CUSTOMER_MODEL CM
ON     CM.COMPANY_CODE = IM.COMPANY_CODE
AND    CM.ITEM_CODE = IM.ITEM_CODE
AND    CM.DIVISION_CODE = #{divisionCode}
AND    CM.CUSTOMER_CODE = #{customerCode}
LEFT   OUTER JOIN FTA_AGM_HS_CODE FAHC
ON     FAHC.COMPANY_CODE = IM.COMPANY_CODE
AND    FAHC.ITEM_CODE = IM.ITEM_CODE
AND    FAHC.FTA_CODE = #{ftaCode}
LEFT   OUTER JOIN FTA_HS_CODE FHC
ON     FHC.COMPANY_CODE = IM.COMPANY_CODE
AND    IM.ITEM_CODE = FHC.ITEM_CODE
AND    FHC.NATION_CODE = #{nationCode}
LEFT   OUTER JOIN HISTORY_ITEM_HS_CODE HIS
ON     HIS.ITEM_CODE = #{itemCode}
AND    HIS.COMPANY_CODE = #{companyCode}
AND    #{resolvedBaseDate} BETWEEN HIS.FROM_DATE AND COALESCE(HIS.TO_DATE, '99991231')
WHERE  IM.ITEM_CODE = #{itemCode}
AND    IM.COMPANY_CODE = #{companyCode}
FETCH FIRST 1 ROW ONLY

SELECT V.COMPANY_CODE AS reqCompanyCode ,V.DIVISION_CODE AS reqDivisionCode ,V.CUSTOMER_CODE AS reqCustomerCode ,V.ITEM_CODE AS reqItemCode ,V.NATION_CODE AS reqNationCode ,V.FTA_CODE AS reqFtaCode ,V.REQ_BASE_DATE AS reqBaseDate ,R.customerHsCode ,R.ftaAgmHsCode ,R.ftaHsCode ,R.historyHsCode ,R.itemHsCode FROM (
SELECT #{r.companyCode} AS COMPANY_CODE, #{r.divisionCode} AS DIVISION_CODE, #{r.customerCode} AS CUSTOMER_CODE, #{r.itemCode} AS ITEM_CODE, #{r.nationCode} AS NATION_CODE, #{r.ftaCode} AS FTA_CODE, #{r.resolvedBaseDate} AS BASE_DATE, #{r.baseDate} AS REQ_BASE_DATE
) V LEFT JOIN LATERAL (SELECT CM.CUSTOMER_HS_CODE AS customerHsCode ,FAHC.FTA_AGM_HS_CODE AS ftaAgmHsCode ,FHC.FTA_HS_CODE AS ftaHsCode ,HIS.HS_CODE AS historyHsCode ,IM.HS_CODE AS itemHsCode FROM ITEM_MST IM LEFT OUTER JOIN CUSTOMER_MODEL CM ON CM.COMPANY_CODE = IM.COMPANY_CODE AND CM.ITEM_CODE = IM.ITEM_CODE AND CM.DIVISION_CODE = V.DIVISION_CODE AND CM.CUSTOMER_CODE = V.CUSTOMER_CODE LEFT OUTER JOIN FTA_AGM_HS_CODE FAHC ON FAHC.COMPANY_CODE = IM.COMPANY_CODE AND FAHC.ITEM_CODE = IM.ITEM_CODE AND FAHC.FTA_CODE = V.FTA_CODE LEFT OUTER JOIN FTA_HS_CODE FHC ON FHC.COMPANY_CODE = IM.COMPANY_CODE AND IM.ITEM_CODE = FHC.ITEM_CODE AND FHC.NATION_CODE = V.NATION_CODE LEFT OUTER JOIN HISTORY_ITEM_HS_CODE HIS ON HIS.ITEM_CODE = V.ITEM_CODE AND HIS.COMPANY_CODE = V.COMPANY_CODE AND V.BASE_DATE BETWEEN HIS.FROM_DATE AND COALESCE(HIS.TO_DATE, '99991231') WHERE IM.ITEM_CODE = V.ITEM_CODE AND IM.COMPANY_CODE = V.COMPANY_CODE FETCH FIRST 1 ROW ONLY) R ON TRUE
